import{z as d,x as m,o as r,c,q as s,j as l,D as e,d as t,s as i,S as E,b as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"一次一密与完美保密","description":"","frontmatter":{"title":"一次一密与完美保密","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/one-time-pad-perfect-secrecy.md","filePath":"cs/one-time-pad-perfect-secrecy.md","lastUpdated":1791413859000}'),p={name:"cs/one-time-pad-perfect-secrecy.md"};function A(h,a,f,u,B,D){const o=m("Mermaid");return r(),c("div",null,[a[2]||(a[2]=s('<h1 id="一次一密与完美保密" tabindex="-1">一次一密与完美保密 <a class="header-anchor" href="#一次一密与完美保密" aria-label="Permalink to &quot;一次一密与完美保密&quot;">​</a></h1><div class="epigraph"><p>若密钥与明文等长、均匀、只用一次，密文的分布与明文无关：看见密文不改变对明文的任何先验。这是信息论极限，不是 AES 圈数能逼近的同一种对象。</p><footer>—— Shannon, Communication Theory of Secrecy Systems, Bell System Technical Journal, 1949</footer></div><p><a href="/cs/to-systems-boundary">上一课</a>把计算机栏停在系统栈：组成到安全，不含 Transformer，不进限价簿。安全进阶从这里另起：主干<a href="/cs/symmetric-crypto">对称加密</a>已点名 Shannon 极限，但只收到「计算安全 + AEAD」。缺口是把<strong>完美保密</strong>写成定理，并说明一次一密为何几乎不能当协议原语。后课默认：完善保密 = 密文独立于明文；实践走计算不可区分。不把 TLA+ 当加密证明。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/dolev-yao">Dolev–Yao</a>把加密当理想锁；真实世界要问锁漏多少。<a href="/cs/bit-as-distinction">比特</a>能编码消息，但窃听者看见的是密文。Shannon：完善保密当且仅当（在密钥均匀且独立于明文时）密钥空间至少与明文一样大——一次一密 \\(c=m\\oplus k\\) 达到该界。缺口不是再讲 CIA 词条，而是：<strong>信息论安全与计算安全从此分叉</strong>。</p><h3 id="不是「更长的-aes」" tabindex="-1">不是「更长的 AES」 <a class="header-anchor" href="#不是「更长的-aes」" aria-label="Permalink to &quot;不是「更长的 AES」&quot;">​</a></h3><p>把 AES-256 说成「接近一次一密」是范畴错误。分组密码在多项式敌手下不可区分于随机置换；一次一密对无界敌手成立，但密钥不能复用、不能压缩。后课 PRG 正是为了丢掉等长密钥。</p><p><span class="marginnote">Katz and Lindell 把完善保密写成：对任意 \\(m_0,m_1\\)，密文分布相同。Vernam 电报是工程形态；Shannon 给出充要条件。密钥复用使两段密文之差等于明文之差，完善性立刻消失。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写一次一密：\\(k\\leftarrow\\{0,1\\}^n\\) 均匀，\\(c=m\\oplus k\\)。证明：固定 \\(c\\)，每个 \\(m\\) 对应唯一 \\(k\\)，故后验等于先验。对照：密钥短于明文则存在信息论区分。指出实践失败几乎全是密钥管理：复用、伪随机不足、同步丢失。</p><p><span class="marginnote">直觉类比：把 XOR 想成「翻硬币」——用公平硬币（均匀密钥）把任何硬币序列翻一遍，结果仍是公平硬币。密文 \\(c\\) 看起来就是纯随机串，窃听者看与不看，对 \\(m\\) 的判断毫无变化，这正是「后验等于先验」。</span></p>',12)),(r(),l(E,null,{default:e(()=>[i(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%98%8E%E6%96%87%20m%22%5D%20--%3E%20XOR%5B%22c%20%3D%20m%20%E2%8A%95%20k%22%5D%0A%20%20K%5B%22%E5%9D%87%E5%8C%80%E4%B8%80%E6%AC%A1%E6%80%A7%E5%AF%86%E9%92%A5%22%5D%20--%3E%20XOR%0A%20%20XOR%20--%3E%20C%5B%22%E5%AF%86%E6%96%87%E4%B8%8E%20m%20%E7%8B%AC%E7%AB%8B%22%5D%0A%20%20C%20--%3E%20PRG%5B%22%E5%90%8E%E8%AF%BE%3A%20%E7%94%A8%20PRG%20%E6%8B%89%E9%95%BF%E7%9F%AD%E7%A7%8D%E5%AD%90%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"完善保密服务无界窃听者，不服务完整性：改 \\(c\\) 等于改 \\(m\\)，接收方无法发觉。主干 AEAD 要的是主动敌手下的计算安全，一次一密不自动给认证。密钥如何生成与分发，等长真随机几乎把问题还原成「先有一条同样宽的保密信道」。",-1)),a[5]||(a[5]=n("p",null,"密钥一旦复用，完善保密立刻蒸发——窃听者用两条密文把密钥消掉：",-1)),(r(),l(E,null,{default:e(()=>[i(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20M1%5B%22%E6%98%8E%E6%96%87%20m1%22%5D%20--%3E%20X1%5B%22c1%20%3D%20m1%20%E2%8A%95%20k%22%5D%0A%20%20M2%5B%22%E6%98%8E%E6%96%87%20m2%22%5D%20--%3E%20X2%5B%22c2%20%3D%20m2%20%E2%8A%95%20k%22%5D%0A%20%20X1%20--%3E%20ATT%5B%22%E7%AA%83%E5%90%AC%E8%80%85%E7%AE%97%20c1%20%E2%8A%95%20c2%22%5D%0A%20%20X2%20--%3E%20ATT%0A%20%20ATT%20--%3E%20OUT%5B%22k%20%E6%B6%88%E6%8E%89%2C%20%E5%BE%97%E5%88%B0%20m1%20%E2%8A%95%20m2%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">常见误区：初学者以为「完美保密」也防篡改。实际上翻转密文 \\(c\\) 的第 \\(i\\) 位就精确翻转明文 \\(m\\) 的第 \\(i\\) 位，接收方毫无察觉。保密与完整是两回事；AEAD 补的是认证，一次一密不自动给。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把量子密钥分发写成主干替换，不重推熵的公理。不要把「一次一密」印在产品页上却用短口令当 \\(k\\)。后课默认：完美保密已钉死为极限；要用短密钥加密任意长消息，必须引入计算假设下的伪随机。</p><p><span class="marginnote">数字实例：加密 1 GB 的备份，一次一密要求先「绝对安全」地送去恰好 1 GB 的真随机密钥——而送密钥本身就是一个等宽的保密问题。这就是「还原成保密信道」：保密没有被创造，只是被搬家。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共识课停在 Multi-Paxos；本课用 Shannon 把保密收成信息论陈述。</li><li>一次一密达到完善保密，当且仅当密钥等长、均匀、不复用。</li><li>无完整性；密钥分发与真随机是它自己的缺口。</li><li>后课用 PRG/PRF 把短种子拉成看起来随机的长串。</li><li>出处：Shannon, 1949；Katz and Lindell, <em>Introduction to Modern Cryptography</em>；对照 Vernam。</li></ul>',6))])}const S=d(p,[["render",A]]);export{_ as __pageData,S as default};
